import {categories,money,localDay,monthOf,normalizeDate,validateTransaction,exportCSV,importCSV,totals} from './core.js';
const $=id=>document.getElementById(id);
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
let storageAvailable=true;function read(key){try{return localStorage.getItem(key);}catch{storageAvailable=false;return null;}}function write(key,value){try{localStorage.setItem(key,value);return true;}catch{toast('บันทึกไม่ได้: พื้นที่เต็ม หรือเบราว์เซอร์ปิดการเก็บข้อมูล');return false;}}
let corruptData=false,transactions=[];try{const raw=read('transactions');if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw Error();transactions=parsed.map(validateTransaction);if(transactions.some(x=>!x))throw Error();}}catch{transactions=[];corruptData=true;}
let budget=Number(read('monthlyBudget'))||0;if(!Number.isFinite(budget)||budget<0)budget=0;
document.body.classList.toggle('dark-mode',read('theme')!=='light');
let pin='',firstPin='',pinMode='unlock',busy=false,attempts=0,blockedUntil=0,unlocked=false,activeTab='home';
let pinRecord=null;try{pinRecord=JSON.parse(read('jodjai-pin-v2')||'null');if(pinRecord&&(!/^[a-f0-9]{32}$/.test(pinRecord.salt)||!/^[a-f0-9]{64}$/.test(pinRecord.hash)))throw Error();}catch{pinRecord={invalid:true};}
let legacyPin=read('appPin');if(!pinRecord&&!legacyPin)pinMode='setup';
function pinTitle(){ $('pin-title').textContent=pinMode==='setup'?'ตั้งรหัส PIN 4 หลัก':pinMode==='confirm'?'ยืนยันรหัส PIN อีกครั้ง':pinMode==='change'?'กรอกรหัส PIN ปัจจุบัน':'กรอกรหัส PIN 4 หลัก';$('pin-subtitle').textContent=pinMode==='confirm'?'กรอกรหัสเดิมอีกครั้งเพื่อยืนยัน':'เพื่อความเป็นส่วนตัวของคุณ';}
function dots(){document.querySelectorAll('#pin-display i').forEach((d,i)=>d.classList.toggle('filled',i<pin.length));$('pin-display').setAttribute('aria-label',`กรอกแล้ว ${pin.length} จาก 4 หลัก`);}
function digit(n){if(busy)return;if(pin.length<4){pin+=n;dots();$('pin-error').textContent='';}}
function clearPin(){if(busy)return;pin='';dots();}
async function hashPin(value,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(v=>v.toString(16).padStart(2,'0')).join('');}
async function storePin(value){const salt=[...crypto.getRandomValues(new Uint8Array(16))].map(v=>v.toString(16).padStart(2,'0')).join('');const record={salt,hash:await hashPin(value,salt)};if(!write('jodjai-pin-v2',JSON.stringify(record)))throw Error('ไม่สามารถบันทึก PIN ได้');pinRecord=record;try{localStorage.removeItem('appPin');}catch{}legacyPin=null;}
async function submitPin(){if(busy)return;if(Date.now()<blockedUntil){$('pin-error').textContent='กรอกรหัสผิดหลายครั้ง กรุณารอ 30 วินาที';return;}if(pin.length!==4){$('pin-error').textContent='กรุณากรอก PIN ให้ครบ 4 หลัก';return;}busy=true;$('pin-ok').disabled=true;try{if(pinMode==='setup'){firstPin=pin;pinMode='confirm';}else if(pinMode==='confirm'){if(pin!==firstPin)throw Error('PIN ไม่ตรงกัน กรุณายืนยันอีกครั้ง');await storePin(pin);firstPin='';unlock();}else{const matches=pinRecord&&!pinRecord.invalid?await hashPin(pin,pinRecord.salt)===pinRecord.hash:!pinRecord&&pin===legacyPin;if(!matches){attempts++;if(attempts>=5){blockedUntil=Date.now()+30000;attempts=0;}throw Error('PIN ไม่ถูกต้อง');}attempts=0;if(pinMode==='change'){pinMode='setup';}else{if(legacyPin)await storePin(pin);unlock();}}pin='';dots();pinTitle();}catch(e){$('pin-error').textContent=e.message||'ไม่สามารถตรวจสอบ PIN ได้';pin='';dots();}finally{busy=false;$('pin-ok').disabled=false;}}
function unlock(){unlocked=true;pinMode='unlock';$('pin-screen').hidden=true;$('main-app').hidden=false;render();if(corruptData)toast('ข้อมูลเดิมเสียหาย: หยุดการเขียนทับ กรุณาสำรองข้อมูลดิบจากหน้าตั้งค่า');}
function lock(mode='unlock'){document.querySelectorAll('dialog[open]').forEach(d=>d.close());unlocked=false;pinMode=mode;pin='';dots();$('main-app').hidden=true;$('pin-screen').hidden=false;$('pin-error').textContent='';pinTitle();}
document.querySelectorAll('[data-digit]').forEach(b=>b.onclick=()=>digit(b.dataset.digit));$('pin-clear').onclick=clearPin;$('pin-ok').onclick=submitPin;
document.addEventListener('keydown',e=>{if(unlocked)return;if(/^\d$/.test(e.key)){e.preventDefault();digit(e.key);}else if(e.key==='Backspace'){e.preventDefault();if(!busy){pin=pin.slice(0,-1);dots();}}else if(e.key==='Escape')clearPin();else if(e.key==='Enter'){e.preventDefault();submitPin();}});
$('lock-btn').onclick=()=>lock();$('change-pin').onclick=()=>lock('change');pinTitle();
if(!storageAvailable){$('pin-error').textContent='กรุณาอนุญาตให้เบราว์เซอร์จัดเก็บข้อมูลก่อนใช้งาน';$('pin-ok').disabled=true;}
$('theme-toggle').onclick=()=>{const dark=!document.body.classList.contains('dark-mode');document.body.classList.toggle('dark-mode',dark);write('theme',dark?'dark':'light');$('theme-toggle').textContent=dark?'☀':'☾';};$('theme-toggle').textContent=document.body.classList.contains('dark-mode')?'☀':'☾';
function switchTab(tab){activeTab=tab;for(const name of ['home','analytics','settings'])$(name+'-panel').hidden=name!==tab;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});render();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
function el(tag,className,text){const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n;}
let selectedCategory='';for(const cat of categories){for(const target of ['cat-scroll-container','modal-categories']){const b=el('button','cat-item');b.type='button';b.append(el('span','cat-icon',cat.icon),el('span','',cat.name));if(target==='modal-categories'){b.dataset.category=cat.id;b.setAttribute('aria-pressed','false');b.onclick=()=>selectCategory(cat.id);}else b.onclick=()=>openAdd(cat.id);$(target).append(b);}}
function selectCategory(id){selectedCategory=id;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===id)));}
function openAdd(category=''){if(!unlocked)return;$('transaction-form').reset();$('date-input').value=localDay();$('form-error').textContent='';selectCategory(category);$('add-modal').showModal();$('amount-input').focus();}
$('add-top').onclick=()=>openAdd();$('add-nav').onclick=()=>openAdd();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function persist(next){if(corruptData){toast('ข้อมูลเดิมเสียหาย จึงยังไม่เขียนทับ กรุณาสำรองข้อมูลดิบก่อน');return false;}if(!write('transactions',JSON.stringify(next)))return false;transactions=next;render();return true;}
$('transaction-form').onsubmit=e=>{e.preventDefault();if(!selectedCategory){$('form-error').textContent='กรุณาเลือกหมวดหมู่';return;}const tx=validateTransaction({id:crypto.randomUUID(),amount:Number($('amount-input').value),category:selectedCategory,note:$('note-input').value.trim(),date:normalizeDate($('date-input').value)});if(!tx){$('form-error').textContent='กรุณาตรวจสอบจำนวนเงินและวันที่';return;}if(persist([...transactions,tx])){$('add-modal').close();toast('จดรายจ่ายเรียบร้อยแล้ว');}};
$('set-budget-btn').onclick=()=>{$('budget-input').value=budget;$('budget-modal').showModal();};$('budget-form').onsubmit=e=>{e.preventDefault();const value=Number($('budget-input').value);if(!Number.isFinite(value)||value<0||value>999999999)return;if(write('monthlyBudget',String(value))){budget=value;$('budget-modal').close();render();toast('บันทึกงบประมาณแล้ว');}};
function renderDashboard(){const t=totals(transactions);$('current-date-display').textContent=new Date().toLocaleDateString('th-TH',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('today-total').textContent=money(t.today);$('month-total').textContent=money(t.month)+(budget?' / '+money(budget):'');$('month-total').classList.toggle('over-budget',budget>0&&t.month>budget);$('budget-fill').style.width=budget?Math.min(100,t.month/budget*100)+'%':'0%';$('budget-fill').style.background=budget&&t.month>budget?'#ed7e6c':'var(--gold)';$('budget-caption').textContent=budget?(t.month>budget?'เกินงบไป '+money(t.month-budget):'เหลืองบอีก '+money(budget-t.month)):'ตั้งงบสักนิด เพื่อวางแผนเดือนนี้';$('set-budget-btn').textContent=budget?'ปรับงบประมาณ →':'ตั้งงบประมาณ →';}
function renderTransactions(){const filter=$('list-filter').value;const now=localDay();const list=transactions.filter(t=>filter==='all'||(filter==='today'?localDay(new Date(t.date))===now:monthOf(t.date)===now.slice(0,7))).sort((a,b)=>new Date(b.date)-new Date(a.date));$('list-title').textContent=filter==='today'?'รายการวันนี้':filter==='month'?'รายการเดือนนี้':'รายการทั้งหมด';const container=$('transaction-list');container.replaceChildren();if(!list.length){const empty=el('div','empty-state');empty.append(el('span','empty-icon','✎'),el('strong','',filter==='today'?'วันนี้ยังว่างอยู่':'ยังไม่มีรายการในช่วงนี้'),el('p','','เริ่มจดรายจ่าย แล้วค่อย ๆ รู้จักการใช้เงินของตัวเอง'));container.append(empty);return;}for(const tx of list){const cat=categories.find(c=>c.id===tx.category);const item=el('article','transaction-item');const detail=el('div','tx-detail');detail.append(el('strong','',cat.name),el('small','',tx.note||'ไม่ได้ระบุหมายเหตุ'));if(filter!=='today')detail.append(el('small','',new Date(tx.date).toLocaleDateString('th-TH')));const remove=el('button','delete-btn','×');remove.setAttribute('aria-label',`ลบรายการ ${cat.name} ${money(tx.amount)}`);remove.onclick=()=>{if(confirm(`ลบรายจ่าย ${cat.name} ${money(tx.amount)}?`))persist(transactions.filter(t=>t.id!==tx.id));};item.append(el('span','cat-icon',cat.icon),detail,el('span','tx-amount',money(tx.amount)),remove);container.append(item);}}
$('list-filter').onchange=renderTransactions;$('analytics-month').value=localDay().slice(0,7);$('analytics-month').onchange=renderChart;
function renderChart(){const month=$('analytics-month').value;const sums=new Map();for(const t of transactions.filter(t=>monthOf(t.date)===month))sums.set(t.category,(sums.get(t.category)||0)+Math.round(t.amount*100));const rows=[...sums].sort((a,b)=>b[1]-a[1]);const total=rows.reduce((n,r)=>n+r[1],0);$('chart-total').textContent=money(total/100);$('donut').setAttribute('aria-label',`รายจ่ายรวม ${money(total/100)} จาก ${rows.length} หมวดหมู่`);const ranking=$('category-rankings');ranking.replaceChildren(el('h2','','อันดับรายจ่าย'));let position=0;const stops=[];rows.forEach(([id,cents],i)=>{const cat=categories.find(c=>c.id===id);const color=`hsl(${(38+i*137.508)%360} 55% 59%)`;const percent=cents/total*100;stops.push(`${color} ${position}% ${position+percent}%`);position+=percent;const row=el('div','ranking');row.append(el('span','',`${cat.icon} ${cat.name}`),el('strong','',money(cents/100)+' · '+Math.round(percent)+'%'));const bar=el('div','ranking-bar');const fill=el('i');fill.style.width=percent+'%';fill.style.background=color;bar.append(fill);row.append(bar);ranking.append(row);});$('donut').style.background=total?`conic-gradient(${stops.join(',')})`:'var(--line)';if(!rows.length)ranking.append(el('p','empty-state','ยังไม่มีข้อมูลรายจ่ายในเดือนนี้'));}
function render(){renderDashboard();renderTransactions();if(activeTab==='analytics')renderChart();}
function download(content,name,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export-btn').onclick=()=>{if(corruptData){download(read('transactions')||'','JodJai_recovery.json','application/json');return;}if(!transactions.length){toast('ยังไม่มีข้อมูลให้ส่งออก');return;}download(exportCSV(transactions),`JodJai_${localDay()}.csv`,'text/csv;charset=utf-8');};
$('import-btn').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('ไฟล์ต้องมีขนาดไม่เกิน 5 MB');const result=importCSV(await file.text(),transactions);const summary=`รายการใหม่ ${result.added} · รายการซ้ำ ${result.duplicates} · ไม่ถูกต้อง ${result.skipped}`;$('import-result').textContent=summary;if(!result.added){toast('ไม่พบรายการใหม่ที่ถูกต้อง');return;}if(!confirm(summary+'\nนำข้อมูลใหม่มารวมกับรายการเดิมหรือไม่?'))return;if(persist(result.transactions))toast(`นำเข้าแล้ว ${result.added} รายการ`);}catch(error){$('import-result').textContent=error.message;toast(error.message);}finally{e.target.value='';}};
let hiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenAt=Date.now();else if(unlocked){if(hiddenAt&&Date.now()-hiddenAt>60000)lock();else render();}});setInterval(()=>{if(unlocked&&!document.hidden)renderDashboard();},60000);
window.addEventListener('storage',e=>{if(['transactions','monthlyBudget','appPin','jodjai-pin-v2'].includes(e.key))location.reload();});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install-btn').hidden=false;});$('install-btn').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install-btn').hidden=true;}};
if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./service-worker.js').then(()=>navigator.serviceWorker.ready).then(()=>{$('offline-status').textContent='พร้อมใช้งานออฟไลน์บนอุปกรณ์นี้ หลังเปิดแอปออนไลน์ครั้งแรก';}).catch(()=>{$('offline-status').textContent='ยังเตรียมออฟไลน์ไม่สำเร็จ กรุณาเปิดผ่าน HTTPS และลองใหม่';});}else $('offline-status').textContent='ใช้งานออฟไลน์ได้เมื่อเปิดแอปผ่าน HTTPS หรือ localhost';
